// testdata/conformance.json is generated by scripts/conformance/sync.ts from
// scripts/conformance/cases/*.json. The Python and TypeScript SDKs run the
// same cases, so a behaviour that differs between the SDKs fails here or
// there. See scripts/conformance/README.md for the rules.
const conformancePath = "testdata/conformance.json"

type conformance struct {
	FetchURL []struct {
		Name    string `json:"name"`
		URL     string `json:"url"`
		Allowed bool   `json:"allowed"`
	} `json:"fetch_url"`
	BaseURL []struct {
		Name    string `json:"name"`
		BaseURL string `json:"base_url"`
		Valid   bool   `json:"valid"`
	} `json:"base_url"`
	RetryAfter struct {
		Now   string `json:"now"`
		Cases []struct {
			Name    string   `json:"name"`
			Value   string   `json:"value"`
			Seconds *float64 `json:"seconds"`
		} `json:"cases"`
	} `json:"retry_after"`
	Retry []struct {
		Name       string            `json:"name"`
		Status     int               `json:"status"`
		Headers    map[string]string `json:"headers"`
		Body       string            `json:"body"`
		MaxRetries int               `json:"max_retries"`
		Retried    bool              `json:"retried"`
		Wait       json.RawMessage   `json:"wait"`
		Kind       *string           `json:"kind"`
	} `json:"retry"`
	Errors []struct {
		Name    string            `json:"name"`
		Status  int               `json:"status"`
		Headers map[string]string `json:"headers"`
		Body    string            `json:"body"`
		Expect  struct {
			Kind              string   `json:"kind"`
			Detail            *string  `json:"detail"`
			Code              *string  `json:"code"`
			Type              string   `json:"type"`
			Error             *string  `json:"error"`
			Fix               *string  `json:"fix"`
			Retryable         *bool    `json:"retryable"`
			RetryAfterSeconds *float64 `json:"retry_after_seconds"`
			RequestID         *string  `json:"request_id"`
			Param             *string  `json:"param"`
			Limit             *struct {
				Scope    *string `json:"scope"`
				Window   *string `json:"window"`
				Max      *int    `json:"max"`
				ResetsAt *string `json:"resets_at"`
			} `json:"limit"`
			MessageContains []string `json:"message_contains"`
			MessageExcludes []string `json:"message_excludes"`
			Absent          []string `json:"absent"`
		} `json:"expect"`
	} `json:"errors"`
	Responses []struct {
		Name     string            `json:"name"`
		Endpoint string            `json:"endpoint"`
		Arg      string            `json:"arg"`
		Status   int               `json:"status"`
		Headers  map[string]string `json:"headers"`
		Body     string            `json:"body"`
		Expect   map[string]any    `json:"expect"`
	} `json:"responses"`
	Options []struct {
		Name   string            `json:"name"`
		Option string            `json:"option"`
		Scope  string            `json:"scope"`
		Value  json.RawMessage   `json:"value"`
		Valid  bool              `json:"valid"`
		Skip   map[string]string `json:"skip"`
	} `json:"options"`
	SearchBody []struct {
		Name    string            `json:"name"`
		Query   string            `json:"query"`
		Options map[string]any    `json:"options"`
		Sent    map[string]any    `json:"sent"`
		Skip    map[string]string `json:"skip"`
	} `json:"search_body"`
}

func loadConformance(t *testing.T) *conformance {
	t.Helper()
	raw, err := os.ReadFile(conformancePath)
	if err != nil {
		t.Fatal(err)
	}
	var c conformance
	if err := json.Unmarshal(raw, &c); err != nil {
		t.Fatal(err)
	}
	return &c
}

// knownDifferences are cases Go's types cannot follow although the fixture
// does not skip them, with why. Keep this empty; each entry is a reported
// difference between the SDKs.
var knownDifferences = map[string]string{}

func skipKnown(t *testing.T, name string) {
	t.Helper()
	if why, ok := knownDifferences[name]; ok {
		t.Skip("known difference: " + why)
	}
}

func TestConformanceFixtureIsTheSameInEverySDK(t *testing.T) {
	ours, err := os.ReadFile(conformancePath)
	if err != nil {
		t.Fatal(err)
	}
	for _, other := range []string{
		"../python/tests/fixtures/conformance.json",
		"../typescript/test/fixtures/conformance.json",
	} {
		theirs, err := os.ReadFile(other)
		if err != nil {
			t.Fatal(err)
		}
		if !bytes.Equal(theirs, ours) {
			t.Fatalf("%s differs; run: node scripts/conformance/sync.ts", other)
		}
	}
}

// counted is a keyed client whose server answers every request with h and
// counts them.
func counted(t *testing.T, opts *keenable.Options, h http.Handler) (*keenable.Client, *atomic.Int32) {
	t.Helper()
	var n atomic.Int32
	counting := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		n.Add(1)
		h.ServeHTTP(w, r)
	})
	if opts == nil {
		opts = &keenable.Options{}
	}
	if opts.APIKey == nil {
		key := "k"
		opts.APIKey = &key
	}
	c, _ := start(t, counting, opts)
	return c, &n
}

var okBoth = http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
	if strings.Contains(r.URL.Path, "/v1/fetch") {
		raw(200, `{"url":"https://e.com","content":"c"}`)(w, r)
		return
	}
	raw(200, `{"query":"q","results":[]}`)(w, r)
})

func isInvalid(err error) bool {
	var bad *keenable.InvalidRequestError
	return errors.As(err, &bad)
}

func TestConformanceFetchURL(t *testing.T) {
	for _, tc := range loadConformance(t).FetchURL {
		t.Run(tc.Name, func(t *testing.T) {
			c, n := counted(t, nil, okBoth)
			_, err := c.Fetch(context.Background(), tc.URL)
			if tc.Allowed {
				if err != nil || n.Load() != 1 {
					t.Fatalf("refused: err=%v requests=%d", err, n.Load())
				}
				return
			}
			if !isInvalid(err) || n.Load() != 0 {
				t.Fatalf("allowed: err=%v requests=%d", err, n.Load())
			}
		})
	}
}

func TestConformanceBaseURL(t *testing.T) {
	for _, tc := range loadConformance(t).BaseURL {
		t.Run(tc.Name, func(t *testing.T) {
			base := tc.BaseURL
			c, err := keenable.New(&keenable.Options{BaseURL: &base})
			if tc.Valid != (err == nil) {
				t.Fatalf("err=%v", err)
			}
			if err != nil && !isInvalid(err) {
				t.Fatalf("%T: %v", err, err)
			}
			c.Close()
		})
	}
}

func TestConformanceRetryAfter(t *testing.T) {
	fixture := loadConformance(t).RetryAfter
	now, err := time.Parse(time.RFC3339Nano, fixture.Now)
	if err != nil {
		t.Fatal(err)
	}
	for _, tc := range fixture.Cases {
		t.Run(tc.Name, func(t *testing.T) {
			got, ok := keenable.RetryAfterAt(tc.Value, now)
			if tc.Seconds == nil {
				if ok {
					t.Fatalf("got %v, want none", got)
				}
				return
			}
			if want := time.Duration(*tc.Seconds * float64(time.Second)); !ok || got != want {
				t.Fatalf("got %v (%v), want %v", got, ok, want)
			}
		})
	}
}

// assertKind checks which error class err is.
func assertKind(t *testing.T, err error, kind string) {
	t.Helper()
	if kind == "redirect" {
		var conn *keenable.ConnectionError
		if !errors.As(err, &conn) || !strings.Contains(err.Error(), "redirected") {
			t.Fatalf("want the redirect error, got %T: %v", err, err)
		}
		return
	}
	var api *keenable.APIError
	if !errors.As(err, &api) {
		t.Fatalf("want an APIError, got %T: %v", err, err)
	}
	kinds := map[string]bool{
		"auth":                 errors.As(err, new(*keenable.AuthError)),
		"rate_limit":           errors.As(err, new(*keenable.RateLimitError)),
		"insufficient_credits": errors.As(err, new(*keenable.InsufficientCreditsError)),
	}
	for k, got := range kinds {
		if got != (k == kind) {
			t.Fatalf("kind %s = %v, want %s: %T", k, got, kind, err)
		}
	}
}

func headerList(h map[string]string) []string {
	var out []string
	for k, v := range h {
		out = append(out, k, v)
	}
	return out
}

func TestConformanceRetry(t *testing.T) {
	for _, tc := range loadConformance(t).Retry {
		t.Run(tc.Name, func(t *testing.T) {
			max := tc.MaxRetries
			c, n, _ := scripted(t, &keenable.Options{MaxRetries: &max},
				raw(tc.Status, tc.Body, headerList(tc.Headers)...), okBody)
			_, err := c.Search(context.Background(), "q", nil)
			waits := keenable.TakeWaits()
			if !tc.Retried {
				if err == nil || n.Load() != 1 || len(waits) != 0 {
					t.Fatalf("err=%v requests=%d waits=%v", err, n.Load(), waits)
				}
				assertKind(t, err, *tc.Kind)
				return
			}
			if err != nil || n.Load() != 2 || len(waits) != 1 {
				t.Fatalf("err=%v requests=%d waits=%v", err, n.Load(), waits)
			}
			var backoff string
			if json.Unmarshal(tc.Wait, &backoff) == nil {
				if waits[0] < 375*time.Millisecond || waits[0] > 500*time.Millisecond {
					t.Fatalf("wait %v is not the first backoff step", waits[0])
				}
				return
			}
			var seconds float64
			if err := json.Unmarshal(tc.Wait, &seconds); err != nil {
				t.Fatal(err)
			}
			if want := time.Duration(seconds * float64(time.Second)); waits[0] != want {
				t.Fatalf("wait %v, want %v", waits[0], want)
			}
		})
	}
}

func TestConformanceErrors(t *testing.T) {
	for _, tc := range loadConformance(t).Errors {
		t.Run(tc.Name, func(t *testing.T) {
			skipKnown(t, tc.Name)
			c, _ := counted(t, nil, raw(tc.Status, tc.Body, headerList(tc.Headers)...))
			_, err := c.Search(context.Background(), "q", nil)
			want := tc.Expect
			assertKind(t, err, want.Kind)
			api := apiErrorFrom(t, err)
			check := func(field, got string, want *string) {
				if got != deref(want) {
					t.Errorf("%s = %q, want %q", field, got, deref(want))
				}
			}
			if api.StatusCode != tc.Status || api.Type != want.Type {
				t.Errorf("status %d type %q, want %d %q", api.StatusCode, api.Type, tc.Status, want.Type)
			}
			check("detail", api.Body, want.Detail)
			check("code", api.APICode, want.Code)
			check("error", api.Title, want.Error)
			check("fix", api.Fix, want.Fix)
			check("request_id", api.RequestID, want.RequestID)
			check("param", api.Param, want.Param)
			if !reflect.DeepEqual(api.Retryable, want.Retryable) {
				t.Errorf("retryable %v, want %v", api.Retryable, want.Retryable)
			}
			wantWait := time.Duration(0)
			if want.RetryAfterSeconds != nil {
				wantWait = time.Duration(*want.RetryAfterSeconds * float64(time.Second))
			}
			if api.RetryAfter != wantWait {
				t.Errorf("retry after %v, want %v", api.RetryAfter, wantWait)
			}
			if want.Limit == nil {
				if api.RateLimit != nil {
					t.Errorf("limit %+v, want none", api.RateLimit)
				}
			} else {
				max := 0
				if want.Limit.Max != nil {
					max = *want.Limit.Max
				}
				wantLimit := keenable.RateLimitInfo{Scope: deref(want.Limit.Scope), Window: deref(want.Limit.Window), Max: max, ResetsAt: deref(want.Limit.ResetsAt)}
				if api.RateLimit == nil || *api.RateLimit != wantLimit {
					t.Errorf("limit %+v, want %+v", api.RateLimit, wantLimit)
				}
			}
			msg := err.Error()
			for _, s := range want.MessageContains {
				if !strings.Contains(msg, s) {
					t.Errorf("message %q lacks %q", msg, s)
				}
			}
			for _, s := range want.MessageExcludes {
				if strings.Contains(msg, s) {
					t.Errorf("message %q has %q", msg, s)
				}
			}
			assertAbsent(t, err, want.Absent)
		})
	}
}

// optional is a JSON null as nil, else a pointer to the string.
func optional(v any) *string {
	if s, ok := v.(string); ok {
		return &s
	}
	return nil
}

// optionalOf is v when it holds a T, else nil.
func optionalOf[T any](v any) *T {
	if t, ok := v.(T); ok {
		return &t
	}
	return nil
}

// optionalInt is a fixture number as an int, or nil for null.
func optionalInt(v any) *int {
	if f, ok := v.(float64); ok {
		n := int(f)
		return &n
	}
	return nil
}

func ptrEqual[T comparable](got, want *T) bool {
	return (got == nil && want == nil) || (got != nil && want != nil && *got == *want)
}

func TestConformanceResponses(t *testing.T) {
	for _, tc := range loadConformance(t).Responses {
		t.Run(tc.Name, func(t *testing.T) {
			c, n := counted(t, nil, raw(tc.Status, tc.Body, headerList(tc.Headers)...))
			want := tc.Expect
			var (
				result any
				err    error
			)
			if tc.Endpoint == "search" {
				result, err = c.Search(context.Background(), tc.Arg, nil)
			} else {
				result, err = c.Fetch(context.Background(), tc.Arg)
			}
			if kind, ok := want["error"].(string); ok {
				if err == nil || n.Load() != 1 {
					t.Fatalf("err=%v requests=%d", err, n.Load())
				}
				assertKind(t, err, kind)
				return
			}
			if err != nil {
				t.Fatal(err)
			}
			if tc.Endpoint == "fetch" {
				page := result.(*keenable.Page)
				if page.URL != want["url"] || page.Title != want["title"] || page.Content != want["content"] ||
					!ptrEqual(page.Description, optional(want["description"])) ||
					!ptrEqual(page.Author, optional(want["author"])) ||
					!ptrEqual(page.PublishedAt, optional(want["published_at"])) ||
					page.RequestID != deref(optional(want["request_id"])) ||
					!ptrEqual(page.Truncated, optionalOf[bool](want["truncated"])) ||
					!ptrEqual(page.TotalChars, optionalInt(want["total_chars"])) {
					t.Fatalf("got %+v, want %v", page, want)
				}
				return
			}
			resp := result.(*keenable.SearchResponse)
			if resp.Query != want["query"] || !ptrEqual(resp.Mode, optional(want["mode"])) ||
				resp.RequestID != deref(optional(want["request_id"])) {
				t.Fatalf("got query %q mode %v request id %q, want %v", resp.Query, resp.Mode, resp.RequestID, want)
			}
			results := want["results"].([]any)
			if len(resp.Results) != len(results) {
				t.Fatalf("got %d results, want %d", len(resp.Results), len(results))
			}
			for i, w := range results {
				w := w.(map[string]any)
				r := resp.Results[i]
				if r.Title != w["title"] || r.URL != w["url"] || r.Snippet != w["snippet"] ||
					!ptrEqual(r.Description, optional(w["description"])) ||
					!ptrEqual(r.PublishedAt, optional(w["published_at"])) ||
					!ptrEqual(r.AcquiredAt, optional(w["acquired_at"])) {
					t.Fatalf("result %d: got %+v, want %v", i, r, w)
				}
			}
		})
	}
}

func TestConformanceOptions(t *testing.T) {
	for _, tc := range loadConformance(t).Options {
		t.Run(tc.Name, func(t *testing.T) {
			if why, ok := tc.Skip["go"]; ok {
				t.Skip(why)
			}
			isNull := string(tc.Value) == "null"
			var (
				clientOpts = &keenable.Options{}
				req        keenable.RequestOptions
				query      = "q"
			)
			switch tc.Option {
			case "max_retries":
				var n int
				if !isNull {
					if err := json.Unmarshal(tc.Value, &n); err != nil {
						t.Fatal(err)
					}
				}
				if tc.Scope == "client" && !isNull {
					clientOpts.MaxRetries = &n
				} else if !isNull {
					req.MaxRetries = &n
				}
			case "timeout":
				var seconds float64
				if !isNull {
					if err := json.Unmarshal(tc.Value, &seconds); err != nil {
						t.Fatal(err)
					}
				}
				d := time.Duration(math.Round(seconds * float64(time.Second)))
				if tc.Scope == "client" {
					clientOpts.Timeout = d
				} else if !isNull {
					req.Timeout = &d
				}
			case "headers":
				var h map[string]string
				if err := json.Unmarshal(tc.Value, &h); err != nil {
					t.Fatal(err)
				}
				if tc.Scope == "client" {
					clientOpts.Headers = h
				} else {
					req.Headers = h
				}
			case "query":
				if err := json.Unmarshal(tc.Value, &query); err != nil {
					t.Fatal(err)
				}
			default:
				t.Fatalf("no Go mapping for option %q", tc.Option)
			}
			if tc.Scope == "client" {
				clientOpts.BaseURL = new(string)
				*clientOpts.BaseURL = "https://api.keenable.ai"
				_, err := keenable.New(clientOpts)
				if tc.Valid != (err == nil) || (err != nil && !isInvalid(err)) {
					t.Fatalf("New: err=%v", err)
				}
				if !tc.Valid {
					return
				}
				clientOpts.BaseURL = nil
			}
			c, n := counted(t, clientOpts, okBoth)
			_, err := c.Search(context.Background(), query, &keenable.SearchOptions{RequestOptions: req})
			if tc.Valid {
				// A real socket can outlast a 1 ms deadline; the value was
				// still accepted, which is what this checks.
				var conn *keenable.ConnectionError
				if errors.As(err, &conn) && conn.Timeout() && tc.Option == "timeout" {
					return
				}
				if err != nil || n.Load() != 1 {
					t.Fatalf("err=%v requests=%d", err, n.Load())
				}
				return
			}
			if !isInvalid(err) || n.Load() != 0 {
				t.Fatalf("err=%v requests=%d", err, n.Load())
			}
		})
	}
}

func TestConformanceSearchBody(t *testing.T) {
	for _, tc := range loadConformance(t).SearchBody {
		t.Run(tc.Name, func(t *testing.T) {
			skipKnown(t, tc.Name)
			if why, ok := tc.Skip["go"]; ok {
				t.Skip(why)
			}
			opts := &keenable.SearchOptions{}
			for wire, v := range tc.Options {
				str, _ := v.(string)
				switch wire {
				case "mode":
					opts.Mode = str
				case "site":
					opts.Site = str
				case "published_after":
					opts.PublishedAfter = str
				case "published_before":
					opts.PublishedBefore = str
				case "acquired_after":
					opts.AcquiredAfter = str
				case "acquired_before":
					opts.AcquiredBefore = str
				case "query_time":
					opts.QueryTime = str
				case "snippet_max_length":
					n := int(v.(float64))
					opts.SnippetMaxLength = &n
				case "max_results":
					opts.MaxResults = int(v.(float64))
				default:
					t.Fatalf("no Go mapping for %q", wire)
				}
			}
			key := "k"
			c, seen := start(t, okBoth, &keenable.Options{APIKey: &key})
			if _, err := c.Search(context.Background(), tc.Query, opts); err != nil {
				t.Fatal(err)
			}
			var sent map[string]any
			if err := json.Unmarshal(one(t, seen).Body, &sent); err != nil {
				t.Fatal(err)
			}
			if !reflect.DeepEqual(sent, tc.Sent) {
				t.Fatalf("sent %v, want %v", sent, tc.Sent)
			}
		})
	}
}
